        } else if (std.mem.eql(u8, arg, "--emit-x86-64")) {
            args.emit_x86_64 = true;
        } else if (std.mem.eql(u8, arg, "--emit-arm64")) {
            args.emit_arm64 = true;
        } else if (std.mem.eql(u8, arg, "--emit-c")) {
            args.emit_c = true;
        } else if (std.mem.eql(u8, arg, "-o") or std.mem.eql(u8, arg, "--output")) {
            i += 1;
            if (i < argv.len) {
                args.output_file = argv[i];
            } else {
                std.debug.print("Error: -o requires an argument\n", .{});
                return error.MissingArgument;
            }
        } else if (std.mem.startsWith(u8, arg, "-")) {
            std.debug.print("Error: Unknown option '{s}'\n", .{arg});
            return error.UnknownOption;
        } else {
            // Input file
            if (args.input_file == null) {
                args.input_file = arg;
            } else {
                std.debug.print("Error: Multiple input files not supported\n", .{});
                return error.MultipleInputFiles;
            }
        }
    }

    // Default to C emission if nothing specified
    if (!args.emit_riscv and !args.emit_x86_64 and !args.emit_arm64) {
        args.emit_c = true;
    }

    return args;
}

fn readInputFile(allocator: std.mem.Allocator, path: []const u8) ![]u8 {
    const file = try std.fs.cwd().openFile(path, .{});
    defer file.close();

    const file_size = try file.getEndPos();
    const content = try allocator.alloc(u8, file_size);
    const bytes_read = try file.readAll(content);

    if (bytes_read != file_size) {
        return error.IncompleteRead;
    }

    return content;
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const stdout = std.io.getStdOut().writer();
    const stderr = std.io.getStdErr().writer();

    // Parse command line arguments
    const argv = try std.process.argsAlloc(allocator);
    defer std.process.argsFree(allocator, argv);

    const args = parseArgs(allocator, argv) catch |err| {
        try stderr.print("Error parsing arguments: {}\n", .{err});
        if (argv.len > 0) {
            printUsage(argv[0]);
        }
        return;
    };

    if (args.help) {
        if (argv.len > 0) {
            printUsage(argv[0]);
        }
        return;
    }

    if (args.input_file == null) {
        try stderr.print("Error: No input file specified\n", .{});
        if (argv.len > 0) {
            printUsage(argv[0]);
        }
        return;
    }

    const input_file = args.input_file.?;
    const output_file = args.output_file orelse "a.out";

    // Read input file
    const source = try readInputFile(allocator, input_file);
    defer allocator.free(source);

    try stdout.print("Zig Compiler v0.6.0 (Multi-Backend Phase)\n", .{});
    try stdout.print("Input: {s} ({} bytes)\n", .{ input_file, source.len });

    // ========================================================================
    // TODO: Implement actual compilation pipeline
    // ========================================================================

    if (args.emit_riscv) {
        try stdout.print("Generating RISC-V assembly...\n", .{});

        // For now, generate a simple example RISC-V function
        // In full implementation, parse source → AIR → RiscvCodegen
        try stdout.print("Output: {s}\n", .{output_file});

        const file = try std.fs.cwd().createFile(output_file, .{});
        defer file.close();

        // Example: Simple add function
        try file.writeAll(
            \\.text
            \\.globl add
            \\add:
            \\    addi sp, sp, -32
            \\    sd ra, 24(sp)
            \\    sd s0, 16(sp)
            \\    addi s0, sp, 32
            \\    mv a2, a0              # a2 = a (arg0)
            \\    mv a3, a1              # a3 = b (arg1)
            \\    add a0, a2, a3         # a0 = a + b
            \\    ld ra, 24(sp)
            \\    ld s0, 16(sp)
            \\    addi sp, sp, 32
            \\    ret
            \\
        );

        try stdout.print("✓ RISC-V assembly generated successfully\n", .{});
    } else if (args.emit_x86_64) {
        try stdout.print("Generating x86-64 assembly...\n", .{});

        // For now, generate a simple example x86-64 function
        // In full implementation, parse source → AIR → X86_64Codegen
        try stdout.print("Output: {s}\n", .{output_file});

        const file = try std.fs.cwd().createFile(output_file, .{});
        defer file.close();

        // Example: Simple add function (Intel syntax, NASM)
        try file.writeAll(
            \\section .text
            \\global add
            \\add:
            \\    push rbp
            \\    mov rbp, rsp
            \\    sub rsp, 32
            \\    mov QWORD [rbp-8], rdi   ; a = arg0 (rdi)
            \\    mov QWORD [rbp-16], rsi  ; b = arg1 (rsi)
            \\    mov rax, QWORD [rbp-8]
            \\    mov r10, QWORD [rbp-16]
            \\    add rax, r10             ; rax = a + b
            \\    add rsp, 32
            \\    pop rbp
            \\    ret
            \\
        );

        try stdout.print("✓ x86-64 assembly generated successfully\n", .{});
    } else if (args.emit_c) {
        try stdout.print("Generating C code...\n", .{});
        try stdout.print("Output: {s}\n", .{output_file});

        const file = try std.fs.cwd().createFile(output_file, .{});
        defer file.close();

        // Example: Simple C code
        try file.writeAll(
            \\// Generated C code from Zig
            \\#include <stdio.h>
            \\
            \\long add(long a, long b) {
            \\    return a + b;
            \\}
            \\
            \\int main() {
            \\    printf("add(2, 3) = %ld\n", add(2, 3));
            \\    return 0;
            \\}
            \\
        );

        try stdout.print("✓ C code generated successfully\n", .{});
    }

    try stdout.print("\nCompilation completed.\n", .{});
}

