///
/// Tests:
/// 1-5: Linker initialization and output capture
/// 6-10: Binary execution and stdout validation
/// 11-15: Exit code verification and error handling

const std = @import("std");
const Linker = @import("../src/linker.zig").Linker;

test "linker: init allocates output buffer" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var linker = Linker.init(allocator);
    defer linker.deinit();

    try std.testing.expect(linker.output.items.len == 0);
}

test "linker: deinit frees resources" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var linker = Linker.init(allocator);
    linker.deinit();

    // No crash = success
    try std.testing.expect(true);
}

test "linker: getOutput returns empty on init" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var linker = Linker.init(allocator);
    defer linker.deinit();

    const output = linker.getOutput();
    try std.testing.expect(output.len == 0);
}

test "linker: runBinary captures stdout from echo" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var linker = Linker.init(allocator);
    defer linker.deinit();

    try linker.runBinary("/bin/echo");
    const output = linker.getOutput();

    try std.testing.expect(output.len >= 0);
}

test "linker: runBinary captures multiple lines" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var linker = Linker.init(allocator);
    defer linker.deinit();

    try linker.runBinary("/bin/echo");
    const output = linker.getOutput();

    // echo produces newline
    try std.testing.expect(output.len > 0);
}

test "linker: output buffer persists after execution" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var linker = Linker.init(allocator);
    defer linker.deinit();

    try linker.runBinary("/bin/echo");
    const output1 = linker.getOutput();

    try linker.runBinary("/bin/echo");
    const output2 = linker.getOutput();

    try std.testing.expect(output2.len > 0);
}

test "linker: close stdin properly" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var linker = Linker.init(allocator);
    defer linker.deinit();

    // /bin/cat would hang without stdin close
    // /bin/true exits immediately
    try linker.runBinary("/bin/true");

    try std.testing.expect(true);
}

test "linker: handle binary not found gracefully" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var linker = Linker.init(allocator);
    defer linker.deinit();

    // This should fail but not crash
    _ = linker.runBinary("/nonexistent/binary") catch {
        try std.testing.expect(true);
        return;
    };
